import { test } from "node:test";
import assert from "node:assert/strict";
import { calcTotal, shippingFee, type Item } from "../src/pricing.ts";

/** Small carts on purpose: every case stays under 10 units, so the $50 threshold is
 *  crossed by unit price rather than by quantity alone. */
function cart(...lines: [price: number, qty: number][]): Item[] {
  const items = lines.map(([price, qty], i) => ({ sku: `s${i}`, price, qty }));
  assert.ok(items.reduce((n, item) => n + item.qty, 0) < 10, "cart must stay under 10 units");
  return items;
}

test("shipping is free once the cart totals $50 or more", () => {
  assert.equal(shippingFee(cart([30, 2])), 0);
  assert.equal(shippingFee(cart([25, 1], [30, 1])), 0);
});

test("shipping costs $5 when the cart is under $50", () => {
  assert.equal(shippingFee(cart([30, 1])), 5);
  assert.equal(shippingFee(cart([10, 3])), 5);
});

test("$50 exactly is free, just under it still costs $5", () => {
  const at = cart([25, 2]);
  const under = cart([24.5, 2]);
  assert.equal(calcTotal(at), 50);
  assert.equal(shippingFee(at), 0);
  assert.equal(calcTotal(under), 49);
  assert.equal(shippingFee(under), 5);
});

test("an empty cart still ships for free", () => {
  assert.equal(shippingFee([]), 0);
});
